INSERT INTO changelog (title, body, created_at) VALUES
('Джері сам бачить задачу і рекламу клієнта',
'Тепер з кожним твоїм повідомленням Джері отримує свіжий стан: відкриту задачу (або ту, яку закрив не більше 20 хв тому) — з усіма галочками, які ти відмітив, інструкцією і посиланнями; і знімок клієнта — кабінет Meta, кампанії з цілями і бюджетами, групи оголошень з частотою, активні креативи з текстами і цифрами (CTR, ліди, ціна ліда), тривоги, останній розбір, задачі в роботі. Не треба казати «подивись» — питай одразу: «що лишилось по цій задачі?», «що в рекламі зараз не так?». Обмеження: лід-форми (питання форми) з Meta поки не тягнуться — для цього потрібен окремий доступ до сторінки. Тумблер «Джері сам бачить контекст» у «Можливостях» (повідомлення трохи дорожчі).',
'2026-11-01 18:00:00');
